CREATE COLUMN TABLE "TEST_AP"."@OFFTAKE_GRN" ("Code" NVARCHAR(50) NOT NULL , "Name" NVARCHAR(100) NOT NULL , "U_STT" INTEGER CS_INT, "U_CodeSource" INTEGER CS_INT, "U_TotalFormular" NVARCHAR(200), PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
